'use strict';

// MODULES //

var tape = require('tape');
var Float16Array = require('./../lib/polyfill.js');

tape('main export is a function', function test(t) {
	t.ok(true, __filename);
	t.strictEqual(typeof Float16Array, 'function', 'main export is a function');
	t.end();
});

tape('can create a Float16Array from length', function test(t) {
	var arr = new Float16Array(5);
	t.strictEqual(arr.length, 5, 'correct length');
	t.end();
});

tape('can create a Float16Array from an array of numbers', function test(t) {
	var arr = new Float16Array([1.5, 2.25, 3.75]);
	t.strictEqual(arr.length, 3, 'correct length');
	t.ok(Math.abs(arr.get(0) - 1.5) < 0.1, 'approximately 1.5');
	t.ok(Math.abs(arr.get(1) - 2.25) < 0.1, 'approximately 2.25');
	t.ok(Math.abs(arr.get(2) - 3.75) < 0.1, 'approximately 3.75');
	t.end();
});

tape('can set and get values', function test(t) {
	var arr = new Float16Array(3);
	arr.set(0, 10.1);
	arr.set(1, 20.2);
	arr.set(2, 30.3);

	t.ok(Math.abs(arr.get(0) - 10.1) < 0.1, 'approximately 10.1');
	t.ok(Math.abs(arr.get(1) - 20.2) < 0.1, 'approximately 20.2');
	t.ok(Math.abs(arr.get(2) - 30.3) < 0.1, 'approximately 30.3');
	t.end();
});

